<parameter name="content">import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { hasError: false, error: null };

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("[ErrorBoundary] Caught render error:", {
      message: error.message,
      stack: error.stack,
      componentStack: errorInfo.componentStack,
      timestamp: new Date().toISOString(),
    });

    this.props.onError?.(error, errorInfo);
  }

  private handleRetry = () => {
    this.setState({ hasError: false, error: null });
  };

  render() {
    if (!this.state.hasError) {
      return this.props.children;
    }

    if (this.props.fallback) {
      return this.props.fallback;
    }

    return (
      <DefaultFallback error={this.state.error} onRetry={this.handleRetry} />
    );
  }
}

interface FallbackProps {
  error: Error | null;
  onRetry: () => void;
}

function DefaultFallback({ error, onRetry }: FallbackProps) {
  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <span style={styles.icon} aria-hidden>
          ⚠️
        </span>
        <h2 style={styles.heading}>Something went wrong</h2>
        <p style={styles.message}>
          {error?.message ?? "An unexpected error occurred."}
        </p>
        <details style={styles.details}>
          <summary style={styles.summary}>Stack trace</summary>
          <pre style={styles.stack}>{error?.stack ?? "No stack available"}</pre>
        </details>
        <button onClick={onRetry} style={styles.button}>
          Try again
        </button>
      </div>
    </div>
  );
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    display: "flex",
